messages.content:
Tool response:
Tool: find_maintenance_work_orders
Description: Find Maintenance Work Orders
Parameters:
    {
      "type": "object",
      "properties": {
        "vendor_name": {
          "type": "string",
          "description": "Name of the vendor to filter work orders by",
          "title": "Vendor Name"
        },
        "days_back": {
          "type": "integer",
          "description": "Number of days back to filter work orders by creation date (default is 45)",
          "default": 45,
          "title": "Days Back"
        },
        "statuses": {
          "anyOf": [
            {
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            {
              "type": "null"
            }
          ],
          "description": "List of statuses to filter work orders by (Open, In Progress, On Hold)",
          "title": "Statuses"
        }
      },
      "required": [
        "vendor_name"
      ]
    }
